using Avalonia;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Media;
namespace WirePulse;

public sealed class EditorCanvas:Control {
 readonly Func<SceneDocument> document;public string? SelectedId{get;set;}public bool Snapping{get;set;}=true;public event Action? Changed;public event Action? SelectionChanged;public event Action? DragStarted;public event Action? DragEnded;
 Point start;Rect initial;int handle=-1;bool dragging;double? vertical,horizontal;
 public EditorCanvas(Func<SceneDocument> document){this.document=document;Focusable=true;ClipToBounds=true;Cursor=new Cursor(StandardCursorType.Arrow);}
 static double Distance(Point a,Point b)=>Math.Sqrt(Math.Pow(a.X-b.X,2)+Math.Pow(a.Y-b.Y,2));
 SceneItem? Selected=>document().Items.FirstOrDefault(x=>x.Id==SelectedId);
 protected override void OnPointerPressed(PointerPressedEventArgs e){if(!e.GetCurrentPoint(this).Properties.IsLeftButtonPressed)return;Focus();Point point=e.GetPosition(this);var selected=Selected;handle=-1;if(selected is{Visible:true,Locked:false}){var handles=SceneGeometry.Handles(selected.Bounds(Bounds.Size));for(int i=0;i<handles.Length;i++)if(Distance(SceneGeometry.Rotate(handles[i],selected.Bounds(Bounds.Size).Center,selected.Rotation),point)<11){handle=i;break;}}
  if(handle<0){selected=document().Items.LastOrDefault(x=>x.Visible&&!x.Locked&&SceneGeometry.Contains(x.Bounds(Bounds.Size),x.Rotation,point));SelectedId=selected?.Id;SelectionChanged?.Invoke();}if(selected==null||selected.Locked){InvalidateVisual();return;}start=point;initial=selected.Bounds(Bounds.Size);dragging=true;DragStarted?.Invoke();e.Pointer.Capture(this);e.Handled=true;InvalidateVisual();}
 protected override void OnPointerMoved(PointerEventArgs e){var point=e.GetPosition(this);if(dragging&&Selected is{} item){var delta=point-start;if(handle>=0){item.SetBounds(SceneGeometry.ResizeRotated(initial,delta,handle,item.KeepAspect&&!e.KeyModifiers.HasFlag(KeyModifiers.Alt),item.Rotation),Bounds.Size);vertical=horizontal=null;}else{var others=document().Items.Where(x=>x.Id!=item.Id&&x.Visible).Select(x=>x.Bounds(Bounds.Size));var snap=SceneGeometry.Move(initial,delta,Bounds.Size,others,Snapping&&!e.KeyModifiers.HasFlag(KeyModifiers.Alt));item.SetBounds(snap.Rect,Bounds.Size);vertical=snap.Vertical;horizontal=snap.Horizontal;}Changed?.Invoke();InvalidateVisual();e.Handled=true;return;}
  bool resize=Selected is{Locked:false} chosen&&SceneGeometry.Handles(chosen.Bounds(Bounds.Size)).Any(p=>Distance(SceneGeometry.Rotate(p,chosen.Bounds(Bounds.Size).Center,chosen.Rotation),point)<11);Cursor=new Cursor(resize?StandardCursorType.SizeAll:document().Items.Any(x=>x.Visible&&!x.Locked&&SceneGeometry.Contains(x.Bounds(Bounds.Size),x.Rotation,point))?StandardCursorType.Hand:StandardCursorType.Arrow);}
 protected override void OnPointerReleased(PointerReleasedEventArgs e){if(!dragging)return;dragging=false;e.Pointer.Capture(null);vertical=horizontal=null;DragEnded?.Invoke();InvalidateVisual();}
 protected override void OnPointerCaptureLost(PointerCaptureLostEventArgs e){if(dragging){dragging=false;vertical=horizontal=null;DragEnded?.Invoke();InvalidateVisual();}}
 public override void Render(DrawingContext c){c.FillRectangle(Brushes.Transparent,new Rect(Bounds.Size));if(vertical.HasValue)c.DrawLine(new Pen(Brushes.DeepSkyBlue,1),new Point(vertical.Value,0),new Point(vertical.Value,Bounds.Height));if(horizontal.HasValue)c.DrawLine(new Pen(Brushes.DeepSkyBlue,1),new Point(0,horizontal.Value),new Point(Bounds.Width,horizontal.Value));if(Selected is not{} item||!item.Visible)return;Rect rect=item.Bounds(Bounds.Size);var pen=new Pen(item.Locked?Brushes.Orange:Brushes.DeepSkyBlue,2);var corners=new[]{rect.TopLeft,rect.TopRight,rect.BottomRight,rect.BottomLeft}.Select(p=>SceneGeometry.Rotate(p,rect.Center,item.Rotation)).ToArray();for(int i=0;i<4;i++)c.DrawLine(pen,corners[i],corners[(i+1)%4]);if(!item.Locked)foreach(var p in SceneGeometry.Handles(rect).Select(p=>SceneGeometry.Rotate(p,rect.Center,item.Rotation)))c.DrawRectangle(Brushes.White,pen,new Rect(p.X-4,p.Y-4,8,8),2,2);var name=new FormattedText(item.Name+(item.Locked?L10n.Text(" · bloqueado"):""),System.Globalization.CultureInfo.CurrentCulture,FlowDirection.LeftToRight,Typeface.Default,13,Brushes.White);double y=Math.Max(4,rect.Y-28),x=Math.Clamp(rect.X,4,Math.Max(4,Bounds.Width-name.Width-16));c.DrawRectangle(new SolidColorBrush(Color.Parse("#ee15364d")),null,new Rect(x,y,name.Width+14,24),4,4);c.DrawText(name,new Point(x+7,y+3));}
}
